]


class FrozenModel(BaseModel):
    """Base for immutable, strict domain models."""

    model_config = ConfigDict(strict=True, frozen=True, extra="forbid", allow_inf_nan=False)
    schema_version: Literal["negotiator-v2/1"] = SCHEMA_VERSION

    @field_serializer("*", when_used="json")
    def canonical_decimal_fields(self, value):
        return decimal_text(value) if isinstance(value, Decimal) else value

    @field_validator("*")
    @classmethod
    def strict_identity_fields(cls, value, info: ValidationInfo):
        name = info.field_name
        if name.endswith(("_id", "_hash", "_fingerprint")) or name in {"fingerprint", "context_version"}:
            if value is not None and isinstance(value, str):
                if not value.strip() or value != value.strip():
                    raise ValueError(f"{name} must be a nonempty unpadded identifier")
                if name.endswith(("_hash", "_fingerprint")) or name == "fingerprint":
                    if not re.fullmatch(r"[0-9a-f]{64}", value):
                        raise ValueError(f"{name} must be a SHA-256 hex digest")
        return value


"""Safe descriptive operational/economic metrics; human judgments remain unreviewed."""


def decision_metrics(trace):
    selected = next((i for i in trace.evaluations.items if trace.decision
                     and i.candidate.candidate_id == trace.decision.candidate_id), None) if trace.evaluations else None
    offers = ([i for i in trace.evaluations.items if i.disposition == "approved" and i.economic]
              if trace.evaluations else [])
    minimum = min((r.nominal_cost.amount for i in offers for r in i.economic), default=None)
    cost = selected.economic[0].nominal_cost.amount if selected and selected.economic else None
    baseline_id = min(offers, key=lambda i: (min(r.nominal_cost.amount for r in i.economic),
                                           i.candidate.candidate_id)).candidate.candidate_id if offers else None
    calls = trace.model_calls
    selections = [c for c in calls if c.request.task == "select"]
    return {
        "trace_hash": trace.trace_hash,
        "state_version": trace.snapshot.state_version,
        "transport_success": sum(c.result_kind == "success" for c in calls),
        "calls": len(calls),
        "interpretation_admitted": trace.assessment is not None and trace.assessment.status == "ok",
        "selection_admitted": (any(c.consumer_admitted is True for c in selections)
                               if selections and all(c.consumer_admitted is not None for c in selections) else None),
        "fallbacks": sum(c.fallback_used for c in calls),
        "final_action_valid": trace.validation is not None and trace.validation.kind == "valid",
        "latency_s": sum(float(c.elapsed_s) for c in calls),
        "charged_usage": sum(c.charged_tokens for c in calls),
        "usage_known": all(c.usage.input_tokens is not None and c.usage.output_tokens is not None for c in calls),
        "inference_expenditure": 0 if all(c.request.provider_id == "local-fixture" for c in calls) else None,
        "official_cost": str(cost) if cost is not None else None,
        "cost_delta": str(cost - minimum) if cost is not None and minimum is not None else None,
        "different_from_cost_minimum": (selected.candidate.candidate_id != baseline_id
                                        if selected and baseline_id else None),
        "semantic_review": "unreviewed",
        "strategic_justification_review": "unreviewed",
        "diagnostics": [c.diagnostic.model_dump(mode="json") if c.diagnostic else
                        {"stage": "consumer", "category": "unattributable", "error_type": "unknown", "field": "$"}
                        for c in calls if c.diagnostic or c.consumer_admitted is None],
    }
"""Durable request journal and in-memory thread state, so a restarted runner can resume.

Journal: append-only JSONL under the run dir, fsynced per record. Every logical POST writes an
`intent` (move id + exact payload + what the thread looked like) *before* the request leaves;
the outcome is a `done`, `failed` (definite HTTP error, e.g. 422) or `abandoned` (reconciled as
no longer valid). Retries reuse both move id and payload. Sessions are recorded on open so a
restart resumes them instead of opening a duplicate. Clocks are stored as UTC epoch seconds;
monotonic timestamps never cross a restart.
"""

import json
import os
import threading
import time
import uuid
from dataclasses import dataclass, field
from pathlib import Path

OUTCOMES = ("done", "failed", "abandoned", "unresolved")
FINAL_OUTCOMES = ("done", "failed", "abandoned")


def new_move_id() -> str:
    return uuid.uuid4().hex


class Journal:
    def __init__(self, path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.Lock()
        self.records: list[dict] = []
        if self.path.exists():
            raw = self.path.read_bytes()
            offset = 0
            lines = raw.splitlines(keepends=True)
            for index, line in enumerate(lines):
                if line.strip():
                    try:
                        self.records.append(json.loads(line))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        if index != len(lines) - 1:
                            raise ValueError("corrupt journal record before the last line") from None
                        # Keep the damaged bytes for diagnosis; otherwise appending would join
                        # the next valid record onto the partial one and hide all later state.
                        self.path.with_name(self.path.name + ".torn-" + uuid.uuid4().hex[:8]).write_bytes(line)
                        with self.path.open("r+b") as stream:
                            stream.truncate(offset)
                            stream.flush()
                            os.fsync(stream.fileno())
                        break
                offset += len(line)
            else:
                if raw and not raw.endswith(b"\n"):
                    with self.path.open("ab") as stream:
                        stream.write(b"\n")
                        stream.flush()
                        os.fsync(stream.fileno())

    def _write(self, rec: dict) -> dict:
        rec = {"utc": time.time(), **rec}
        line = json.dumps(rec, ensure_ascii=False, default=str)
        with self._lock:
            with self.path.open("a", encoding="utf-8") as f:
                f.write(line + "\n")
                f.flush()
                os.fsync(f.fileno())
            self.records.append(rec)
        return rec

    # -- writes --------------------------------------------------------------------------------
    def intent(self, case_id, session_id, supplier_id, kind, payload, **context) -> dict:
        """Persist a logical POST before sending it. kind: open | send | close."""
        return self._write(
            {
                "rec": "intent",
                "move_id": new_move_id(),
                "case": case_id,
                "session": session_id,
                "supplier": supplier_id,
                "kind": kind,
                "payload": payload,
                **context,
            }
        )

    def outcome(self, move_id: str, outcome: str, **fields) -> dict:
        assert outcome in OUTCOMES
        return self._write({"rec": outcome, "move_id": move_id, **fields})

    def session(self, case_id: str, session_id: str, case: dict | None = None) -> dict:
        return self._write({"rec": "session", "case": case_id, "session": session_id, "case_file": case})

    def result(self, case_id: str, session_id: str | None, result: dict) -> dict:
        return self._write({"rec": "result", "case": case_id, "session": session_id, "result": result})

